actions.script:
if (ec.message.hasError()) return
const terms = offerFound?.offer?.hireTerms
if (!terms) { ec.message.addError('Only an accepted offer is hired from, by HR'); return }
const draft = {organizationPartyId: terms.organizationPartyId, partyId: terms.partyId, firstName: '', lastName: '',
    preferredName: '', workEmail: '', workPhone: '', confirmNewPerson: '', fromDate: terms.fromDate, thruDate: terms.thruDate,
    departmentPartyId: terms.departmentPartyId, emplPositionId: terms.emplPositionId, managerPartyId: terms.managerPartyId,
    facilityId: terms.facilityId, reason: '', employmentOfferId: terms.employmentOfferId}
ec.service.sync().name('mantle.humanres.PeopleServices.store#EmploymentDraft').parameters({draftKind: 'hire',
    employmentDraftId: hireDraftId, draft}).call()
if (!ec.message.hasError()) ec.message.addMessage('The hire starts from the accepted offer: check each step', 'success')

const text = value => String(value ?? '').trim()
const draft = Object.assign({}, hireDraft, {
    organizationPartyId: text(organizationPartyId) || null,
    partyId: text(partyId) || null,
    firstName: text(firstName),
    lastName: text(lastName),
    preferredName: text(preferredName),
    workEmail: text(workEmail),
    workPhone: text(workPhone),
    confirmNewPerson: confirmNewPerson === 'Y' ? 'Y' : ''
})
// kept in the user's draft record (Back loses nothing; the draft's operation key, made once, makes a Hire sent
// twice answer the first)
ec.service.sync().name('mantle.humanres.PeopleServices.store#EmploymentDraft').parameters({draftKind: 'hire',
    employmentDraftId: hireDraftId, draft}).call()
if (ec.message.hasError()) return
if (!draft.organizationPartyId) ec.message.addValidationError(null, 'organizationPartyId', null, 'Choose the employer', null)
if (!draft.partyId && !(draft.firstName && draft.lastName))
    ec.message.addValidationError(null, 'partyId', null, 'Choose the person, or give a new person\'s first and last names', null)
if (ec.message.hasError()) return
const previewed = ec.service.sync().name('mantle.humanres.PeopleServices.preview#Hire').parameters({
    organizationPartyId: draft.organizationPartyId, partyId: draft.partyId, firstName: draft.firstName,
    lastName: draft.lastName, workEmail: draft.workEmail, confirmNewPerson: draft.confirmNewPerson === 'Y',
    employmentOfferId: draft.employmentOfferId || null}).call()
if (ec.message.hasError()) return
// the person's refusals (and an offer's, P17) belong to this step; the terms' to the next
for (const finding of Array.from(previewed?.findings || []))
    if (finding.severity === 'error' && (['PERSON_REQUIRED', 'PERSON_MATCHES'].includes(finding.code) || finding.code.startsWith('OFFER_')))
        ec.message.addError(finding.message)

identity = Object.assign({}, hireDraft)
// a new hire's employer: the active one, else the first of the user's employers with someone employed now
if (!identity.organizationPartyId && hireOrganizations.length) {
    identity.organizationPartyId = people.activeOrganizationPartyId || hireOrganizations.find(organizationPartyId =>
        ec.entity.find('mantle.party.PartyRelationship').condition({relationshipTypeEnumId: 'PrtEmployee',
            toPartyId: organizationPartyId}).conditionDate('fromDate', 'thruDate', null).disableAuthz().count() > 0)
        || hireOrganizations[0]
}
